// Snapshot counts are based on the published Pages SHA, not a mutable main checkout.
export async function dashboardSnapshot(fetcher=fetch){
 const jsonAt=async url=>{const r=await fetcher(url,{redirect:'manual',headers:{Accept:'application/json','User-Agent':'Korean-Backoffice-Dashboard','Cache-Control':'no-cache'},signal:AbortSignal.timeout(10000)});if(r.status!==200)throw Error('upstream');return r.json();};
 const release=await jsonAt('https://duykhang68.github.io/khoahoctienghan/release-sha.json');
 const sha=release?.sha;if(typeof sha!=='string'||! /^[a-f0-9]{40}$/.test(sha))throw Error('invalid release SHA');
 const [tree,posts]=await Promise.all([jsonAt('https://api.github.com/repos/duykhang68/khoahoctienghan/git/trees/'+sha+'?recursive=1'),jsonAt('https://raw.githubusercontent.com/duykhang68/khoahoctienghan/'+sha+'/src/data/techblog/posts.json')]);
 if(tree?.truncated!==false||!Array.isArray(tree.tree)||!Array.isArray(posts)||!posts.every(p=>typeof p?.slug==='string'&&p.slug.length>0))throw Error('incomplete snapshot');
 const knowledge=new Set(tree.tree.filter(e=>e.type==='blob'&&typeof e.path==='string'&&/^src\/content\/docs\/(?:[^/]+\/)+[^/]+\.mdx?$/.test(e.path)&&!/(?:^|\/)index\.mdx?$/.test(e.path)).map(e=>e.path.replace(/\.mdx?$/,''))).size;
 const tech=new Set(posts.map(p=>p.slug)).size;if(tech!==posts.length)throw Error('duplicate posts');
 return {sha,tech,knowledge};
}
const studioMarkup="<style>main{max-width:1160px;padding:24px 16px}*{box-sizing:border-box}.studio-head{display:flex;flex-wrap:wrap;justify-content:space-between;align-items:center;gap:16px}.studio-head h1{font-size:clamp(26px,4vw,42px);line-height:1.2}.studio-head p{margin:8px 0}.studio-actions{display:flex;flex-wrap:wrap;gap:10px;align-items:center}.studio-actions form{margin:0}.studio-actions button{font:inherit}.studio-label{letter-spacing:.1em;text-transform:uppercase;font-weight:700;font-size:12px;color:#4338ca}.studio-section{margin:26px 0}.studio-section h2{font-size:21px;margin:0 0 12px}.studio-metrics,.studio-tools{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,205px),1fr));gap:14px}.studio-metrics article,.studio-tools article{padding:20px;border-radius:16px;min-width:0;overflow-wrap:anywhere}.studio-metrics article:nth-child(1){background:#e9e2ff}.studio-metrics article:nth-child(2){background:#d9f3e6}.studio-metrics article:nth-child(3){background:#dcecff}.studio-metrics article:nth-child(4){background:#ffe8d7}.studio-metrics strong{display:block;font-size:32px;line-height:1.3;font-variant-numeric:tabular-nums}.studio-metrics p,.studio-tools p{margin:3px 0;color:#42526b;font-size:14px}.studio-tools article h3{font-size:20px;margin:5px 0}.studio-tools a{display:inline-block;margin-top:12px;color:#3730a3;font-weight:650;text-underline-offset:3px}.studio-meta{overflow-wrap:anywhere;font-size:13px;color:#475569;margin:12px 0}.studio-meta code{font-size:12px}.studio-notice{color:#475569;font-size:14px}.studio-tools article:nth-child(1){background:#f3efff}.studio-tools article:nth-child(2){background:#edf8f0}.studio-tools article:nth-child(3){background:#edf6ff}button:disabled{opacity:.6}:focus-visible{outline:3px solid #2563eb;outline-offset:3px}</style>\n<header class=\"studio-head\"><div><span class=\"studio-label\">P1.1 · DUY NGUYEN EDITORIAL STUDIO</span><h1>Trung tâm quản trị</h1><p>Phiên quản trị đã xác thực · Không gian biên tập thống nhất</p></div><div class=\"studio-actions\"><button id=\"studio-refresh\" type=\"button\">Cập nhật dữ liệu</button><form action=\"/auth/logout\" method=\"post\"><button>Đăng xuất</button></form></div></header>\n<section class=\"studio-section\" aria-labelledby=\"studio-overview\"><h2 id=\"studio-overview\">Tổng quan nội dung</h2><div class=\"studio-metrics\"><article><small>Tech Blog</small><strong id=\"studio-tech\">—</strong><p>Bài trong snapshot phát hành</p></article><article><small>Knowledge Base</small><strong id=\"studio-knowledge\">—</strong><p>Bài học, không gồm trang index</p></article><article><small>Hàng đợi FIFO</small><strong id=\"studio-queue\">—</strong><p>Issue chưa xác minh production</p></article><article><small>Đã xác minh</small><strong id=\"studio-verified\">—</strong><p>Issue FIFO đã đóng, đủ marker</p></article></div><p class=\"studio-meta\" id=\"studio-snapshot\">Chưa tải SHA phát hành.</p><p id=\"studio-content-status\" class=\"studio-notice\" role=\"status\">Đang tải số liệu nội dung…</p><p id=\"studio-queue-status\" class=\"studio-notice\" role=\"status\">Đang tải hàng đợi…</p></section>\n<section class=\"studio-section\" aria-labelledby=\"studio-tools\"><h2 id=\"studio-tools\">Không gian làm việc</h2><div class=\"studio-tools\"><article><span class=\"studio-label\">01 · SOẠN THẢO</span><h3>Editorial Studio V2</h3><p>Viết trực quan, ảnh WebP, sơ đồ và xem trước.</p><a href=\"/admin/editor/\">Mở Tech Blog Editor</a><br><a href=\"/admin/editor/#workspace=knowledge\">Mở Knowledge Base Editor</a></article><article><span class=\"studio-label\">02 · NGUỒN NỘI DUNG</span><h3>Google Sheets Publisher</h3><p>Đọc tab VN và gửi bài vào FIFO.</p><a href=\"/admin/sheets/\">Mở Google Sheets Publisher</a></article><article><span class=\"studio-label\">03 · VẬN HÀNH</span><h3>Engineering Foundation</h3><p>CI/CD, tỷ lệ thành công, sức khỏe kỹ thuật.</p><a href=\"/admin/engineering/\">Mở dashboard kỹ thuật</a></article><article><span class=\"studio-label\">04 · THƯ VIỆN</span><h3>Content Library</h3><p>Tìm và quản lý bài đã xuất bản.</p><a href=\"/admin/library/\">Mở thư viện bài viết</a></article></div></section><p class=\"studio-notice\">Số bài lấy từ snapshot GitHub Pages được phát hành; trạng thái FIFO lấy từ Issue bot hiện tại. Cập nhật thủ công, không tự polling. Không đọc nội dung bản nháp riêng tư hoặc Google Sheet tại dashboard.</p>";
const studioScript="import {queueClient,progressFor} from '/admin/assets/sheet-blog/progress.mjs';\nconst by=id=>document.getElementById(id),btn=by('studio-refresh');\nlet busy=false,contentLoaded=false,queueLoaded=false;\nasync function content(){const status=by('studio-content-status');status.textContent='Đang tải snapshot…';try{const r=await fetch('/admin/api/dashboard/',{cache:'no-store',redirect:'error',signal:AbortSignal.timeout(15000)});if(!r.ok)throw Error('HTTP '+r.status);const d=await r.json();if(!/^[a-f0-9]{40}$/.test(d.sha)||![d.tech,d.knowledge].every(n=>Number.isSafeInteger(n)&&n>=0))throw Error('Invalid snapshot');by('studio-tech').textContent=String(d.tech);by('studio-knowledge').textContent=String(d.knowledge);by('studio-snapshot').textContent='SHA phát hành: '+d.sha;contentLoaded=true;status.textContent='Đã tải snapshot phát hành.';}catch{status.textContent=contentLoaded?'Không tải được snapshot · giữ dữ liệu lần trước.':'Chưa tải được snapshot. Thử cập nhật lại.';}}\nasync function queue(){const status=by('studio-queue-status');status.textContent='Đang đọc Issue FIFO…';try{const rows=await queueClient().list();const unique=[...new Map(rows.map(r=>[r.number,r])).values()];const verified=unique.filter(r=>progressFor(r).done===6).length;by('studio-verified').textContent=String(verified);by('studio-queue').textContent=String(unique.length-verified);queueLoaded=true;status.textContent='Đã tải Issue FIFO · '+new Date().toLocaleString('vi-VN',{timeZone:'Asia/Ho_Chi_Minh'})+' GMT+7';}catch{status.textContent=queueLoaded?'Không tải được FIFO · giữ dữ liệu lần trước.':'Chưa tải được FIFO. Thử cập nhật lại.';}}\nasync function refresh(){if(busy)return;busy=true;btn.disabled=true;try{await Promise.all([content(),queue()]);}finally{busy=false;btn.disabled=false;}}\nbtn.addEventListener('click',refresh);void refresh();";
const engineeringMarkup="<nav aria-label=\"Back Office\"><a href=\"/admin/\">← Trung tâm quản trị</a></nav><section class=\"foundation\"aria-labelledby=\"foundation-title\">\n<header class=\"hero\"><div><p class=\"eyebrow\">P0 / ENGINEERING INTELLIGENCE</p><h1 id=\"foundation-title\">Engineering Foundation</h1><p>Quan sát sức khỏe kỹ thuật của Tri thức Hàn Quốc.</p></div><button id=\"refresh\" type=\"button\">↻ Cập nhật dữ liệu</button></header>\n<p class=\"notice\" id=\"status\" role=\"status\">Đang tải dữ liệu công khai từ GitHub Actions…</p>\n<div class=\"filters\"><label>Workflow <select id=\"workflow\"><option value=\"\">Tất cả</option></select></label><label>Khoảng thời gian <select id=\"period\"><option value=\"7\">7 ngày</option><option value=\"30\" selected>30 ngày</option><option value=\"90\">90 ngày</option></select></label></div>\n<div class=\"metrics\">\n<article class=\"lavender\"><p>Tổng lượt chạy</p><strong id=\"runs\">—</strong></article><article class=\"mint\"><p>Tỷ lệ thành công</p><strong id=\"success\">—</strong></article><article class=\"blue\"><p>Thời gian trung bình (ước tính)</p><strong id=\"duration\">—</strong></article><article class=\"rose\"><p>Lượt thất bại</p><strong id=\"failed\">—</strong></article>\n</div>\n<div class=\"charts\"><article class=\"panel\"><h2>Tỷ lệ thành công theo ngày</h2><p class=\"sub\">Chỉ tính success / (success + failure).</p><svg id=\"trend\" viewBox=\"0 0 600 230\" role=\"img\" aria-label=\"Biểu đồ tỷ lệ thành công theo ngày\"></svg><details><summary>Dữ liệu biểu đồ</summary><ul id=\"trend-data\"></ul></details></article><article class=\"panel\"><h2>Trạng thái pipeline</h2><div id=\"distribution\"></div></article></div>\n<article class=\"panel\"><h2>Hiệu suất workflow</h2><div class=\"tablewrap\"><table><thead><tr><th>Workflow</th><th>Lượt chạy</th><th>Thành công</th><th>Thất bại</th><th>Tỷ lệ</th></tr></thead><tbody id=\"performance\"></tbody></table></div></article>\n<article class=\"panel\"><h2>Lượt chạy gần đây</h2><div class=\"tablewrap\"><table><thead><tr><th>Workflow</th><th>Trạng thái</th><th>Thời gian (GMT+7)</th><th>SHA</th></tr></thead><tbody id=\"recent\"></tbody></table></div></article>\n<p class=\"sub\">Nguồn: <a href=\"https://github.com/duykhang68/khoahoctienghan/actions\">GitHub Actions</a>. Mẫu tối đa 100 lượt chạy mới nhất; không đại diện toàn bộ lịch sử. Không dùng token, không tự polling. Thành công của workflow không đồng nghĩa production đã xác minh.</p>\n</section>";
const engineeringScript="\nconst el=(id)=>document.getElementById(id);\nconst workflow=el('workflow'), period=el('period'), refresh=el('refresh');\nlet runs=[];\nconst state=(r)=>r.status==='completed'?(r.conclusion||'unknown'):r.status;\nconst rate=(a)=>{const s=a.filter(r=>state(r)==='success').length,f=a.filter(r=>state(r)==='failure').length;return s+f?Math.round(s/(s+f)*1000)/10:null};\nconst fmt=(v)=>v===null?'—':v.toLocaleString('vi-VN')+'%';\nconst day=(s)=>new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Ho_Chi_Minh'}).format(new Date(s));\nfunction textCell(row,value){row.insertCell().textContent=value;}\nfunction render(){\n const selected=runs.filter(r=>(!workflow.value||r.name===workflow.value)&&Date.parse(r.created_at)>=Date.now()-Number(period.value)*86400000);\n const done=selected.filter(r=>r.status==='completed'&&r.run_started_at&&Date.parse(r.updated_at)>=Date.parse(r.run_started_at));\n const secs=done.length?Math.round(done.reduce((n,r)=>n+(Date.parse(r.updated_at)-Date.parse(r.run_started_at))/1000,0)/done.length):null;\n el('runs').textContent=String(selected.length);el('success').textContent=fmt(rate(selected));el('failed').textContent=String(selected.filter(r=>state(r)==='failure').length);el('duration').textContent=secs===null?'—':Math.floor(secs/60)+'m '+secs%60+'s';\n const groups=new Map();for(const r of selected){const a=groups.get(r.name)||[];a.push(r);groups.set(r.name,a);}\n const tbody=el('performance');tbody.replaceChildren();for(const [name,a] of groups){const tr=document.createElement('tr');[name,String(a.length),String(a.filter(r=>state(r)==='success').length),String(a.filter(r=>state(r)==='failure').length),fmt(rate(a))].forEach(v=>textCell(tr,v));tbody.append(tr);}\n const colors={success:'#0d9488',failure:'#e11d48',cancelled:'#d97706',in_progress:'#2563eb',queued:'#7c3aed'};\n const dist=el('distribution');dist.replaceChildren();for(const s of [...new Set(selected.map(state))]){const n=selected.filter(r=>state(r)===s).length;const item=document.createElement('div');item.className='distribution-row';const label=document.createElement('p');label.textContent=s+' · '+n+' lượt';const bar=document.createElement('progress');bar.max=selected.length;bar.value=n;bar.setAttribute('aria-label',s);bar.style.accentColor=colors[s]||'#64748b';item.append(label,bar);dist.append(item);}\n const recent=el('recent');recent.replaceChildren();for(const r of selected.slice(0,20)){const tr=document.createElement('tr');const link=document.createElement('a');link.href='https://github.com/duykhang68/khoahoctienghan/actions/runs/'+encodeURIComponent(String(r.id));link.textContent=r.name;tr.insertCell().append(link);textCell(tr,state(r));textCell(tr,new Date(r.created_at).toLocaleString('vi-VN',{timeZone:'Asia/Ho_Chi_Minh'}));textCell(tr,r.head_sha.slice(0,7));recent.append(tr);}\n const dates=[...new Set(selected.map(r=>day(r.created_at)))].sort();const series=dates.map(d=>({d,v:rate(selected.filter(r=>day(r.created_at)===d))})).filter((x)=>x.v!==null);\n const svg=el('trend');svg.replaceChildren();const list=el('trend-data');list.replaceChildren();\n function node(tag,attrs,value){const n=document.createElementNS('http://www.w3.org/2000/svg',tag);for(const [k,v] of Object.entries(attrs))n.setAttribute(k,v);if(value)n.textContent=value;svg.append(n);}\n for(const v of [0,25,50,75,100]){const y=190-v*1.7;node('line',{x1:'48',x2:'580',y1:String(y),y2:String(y),stroke:'#dbe4ef'});node('text',{x:'42',y:String(y+4),'text-anchor':'end',fill:'#475569','font-size':'11'},v+'%');}\n const pts=series.map((s,i)=>({x:48+(series.length===1?266:i*532/(series.length-1)),y:190-s.v*1.7,...s}));\n if(pts.length){node('polygon',{points:[pts[0].x+',190',...pts.map(p=>p.x+','+p.y),pts[pts.length-1].x+',190'].join(' '),fill:'#ccfbf1'});node('polyline',{points:pts.map(p=>p.x+','+p.y).join(' '),fill:'none',stroke:'#0d9488','stroke-width':'3'});}\n for(const [i,p] of pts.entries()){node('circle',{cx:String(p.x),cy:String(p.y),r:'4',fill:'#0d9488'});if(i===0||i===pts.length-1||i%Math.ceil(pts.length/5)===0)node('text',{x:String(p.x),y:'212','text-anchor':'middle',fill:'#475569','font-size':'10'},p.d.slice(5));const li=document.createElement('li');li.textContent=p.d+': '+fmt(p.v);list.append(li);}\n if(!pts.length)node('text',{x:'310',y:'110','text-anchor':'middle',fill:'#475569'},'Chưa đủ dữ liệu');\n if(!selected.length){dist.textContent='Không có lượt chạy trong mẫu đã chọn.';for(const body of [tbody,recent]){const tr=document.createElement('tr');const td=tr.insertCell();td.colSpan=5;td.textContent='Không có dữ liệu';body.append(tr);}}\n}\nasync function load(){refresh.disabled=true;el('status').textContent='Đang tải…';try{const res=await fetch('https://api.github.com/repos/duykhang68/khoahoctienghan/actions/runs?per_page=100',{headers:{Accept:'application/vnd.github+json'}});if(!res.ok)throw new Error('HTTP '+res.status);const data=await res.json();if(!Array.isArray(data.workflow_runs))throw new Error('Dữ liệu không hợp lệ');runs=data.workflow_runs;const old=workflow.value;workflow.replaceChildren(new Option('Tất cả',''));for(const name of [...new Set(runs.map(r=>r.name))].sort())workflow.add(new Option(name,name));workflow.value=[...workflow.options].some(o=>o.value===old)?old:'';render();el('status').textContent='Đã tải '+runs.length+' lượt gần nhất · '+new Date().toLocaleString('vi-VN',{timeZone:'Asia/Ho_Chi_Minh'})+' (GMT+7)';}catch{el('status').textContent='Không thể tải GitHub Actions (mạng hoặc giới hạn API). '+(runs.length?'Đang giữ dữ liệu lần tải trước.':'Chưa có dữ liệu.');}finally{refresh.disabled=false;}}\n workflow.addEventListener('change',()=>render());period.addEventListener('change',()=>render());refresh.addEventListener('click',load);load();\n";
const engineeringStyle="main{max-width:1280px} .foundation article{background:white} .foundation .lavender{background:#eef2ff}.foundation .mint{background:#ecfdf5}.foundation .blue{background:#e0f2fe}.foundation .rose{background:#fff1f2}.foundation .hero{border:0} .foundation a,nav a{color:#4338ca}\n.foundation{max-width:1200px;margin:auto;padding:clamp(16px,4vw,48px);color:#17233c;background:#fff;line-height:1.5}.hero{display:flex;justify-content:space-between;align-items:center;gap:16px;flex-wrap:wrap;background:linear-gradient(115deg,#eef2ff,#f0fdfa);border-radius:18px;padding:clamp(18px,4vw,38px)}.hero h1{font-size:clamp(28px,4vw,46px);margin:8px 0;letter-spacing:-.035em}.hero p{margin:0}.eyebrow{font-size:12px;font-weight:700;color:#4338ca;letter-spacing:.12em}.foundation button{background:#4338ca;color:white;border:0;border-radius:9px;padding:12px 18px;font:inherit;cursor:pointer}.foundation button:disabled{opacity:.6}.notice,.sub{color:#475569;font-size:14px}.filters{display:flex;flex-wrap:wrap;gap:16px;margin:20px 0}.filters label{display:grid;gap:5px;font-size:14px;font-weight:600}.filters select{max-width:100%;padding:9px;border:1px solid #cbd5e1;border-radius:8px;color:#17233c;background:#fff;font:inherit}.metrics{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,190px),1fr));gap:14px}.metrics article{padding:20px;border-radius:14px;min-width:0}.metrics p{margin:0 0 8px;font-size:14px}.metrics strong{font-size:30px;font-variant-numeric:tabular-nums}.lavender{background:#eef2ff;color:#4338ca}.mint{background:#ecfdf5;color:#047857}.blue{background:#e0f2fe;color:#075985}.rose{background:#fff1f2;color:#be123c}.charts{display:grid;grid-template-columns:minmax(0,2fr) minmax(0,1fr);gap:16px}.panel{border:1px solid #e2e8f0;border-radius:14px;padding:20px;margin-top:18px;min-width:0}.panel h2{font-size:20px;margin:0 0 12px}.panel svg{width:100%;height:auto}.distribution-row p{font-size:14px;margin:8px 0 3px}.distribution-row progress{width:100%;height:12px}.tablewrap{overflow-x:auto}.panel table{border-collapse:collapse;width:100%;font-size:14px}.panel th,.panel td{text-align:left;padding:12px 8px;border-bottom:1px solid #e2e8f0;overflow-wrap:anywhere}.panel th{background:#f1f5f9}.foundation a{color:#4338ca}.foundation :focus-visible{outline:3px solid #2563eb;outline-offset:3px}@media(max-width:720px){.charts{grid-template-columns:1fr}.panel{padding:12px}.panel table{font-size:12px}.panel th,.panel td{padding:8px 4px}}\n";
