const libraryScript="\nconst by=id=>document.getElementById(id),make=(tag,text)=>{const e=document.createElement(tag);if(text!==undefined)e.textContent=text;return e};\nconst repo='/repos/duykhang68/khoahoctienghan',site='https://duykhang68.github.io/khoahoctienghan/';\nlet snapshot=null,selected=null,loaded=null,busy=false,selection=0,inputs=[];\nconst validSha=s=>typeof s==='string'&&/^[a-f0-9]{40}$/.test(s);\nconst raw=(sha,path)=>'https://raw.githubusercontent.com/duykhang68/khoahoctienghan/'+sha+'/'+path;\nconst source=async(sha,path)=>{const r=await fetch(raw(sha,path),{redirect:'error',cache:'no-store',credentials:'omit',signal:AbortSignal.timeout(15000)});if(!r.ok)throw Error('Không tải được nguồn '+path);return r.text()};\nconst parse=s=>JSON.parse(s);\nconst format=s=>JSON.stringify(s,null,2)+'\\n';\nconst titleField=(source,key)=>{const front=source.match(/^---\\r?\\n([\\s\\S]*?)\\r?\\n---(?:\\r?\\n|$)/);if(!front)throw Error('Metadata không hỗ trợ');const line=front[1].match(new RegExp('^'+key+':[ \\\\t]*(.*)$','m'));if(!line)return '';let value=line[1].trim();if(/^[>|]/.test(value))throw Error('Metadata nhiều dòng cần quy trình chuyển đổi riêng');if(value.startsWith('\"')){try{return JSON.parse(value)}catch{throw Error('Metadata không hỗ trợ')}}if(value.startsWith(\"'\")&&value.endsWith(\"'\"))return value.slice(1,-1).replace(/''/g,\"'\");return value;};\nfunction replaceField(source,key,value){const front=source.match(/^---\\r?\\n([\\s\\S]*?)\\r?\\n---(?:\\r?\\n|$)/);if(!front)throw Error('Metadata không hỗ trợ');titleField(source,key);const rule=new RegExp('^'+key+':[ \\\\t]*.*$','m');const next=rule.test(front[1])?front[1].replace(rule,()=>key+': '+JSON.stringify(value)):front[1]+'\\n'+key+': '+JSON.stringify(value);return source.slice(0,front.index)+front[0].replace(front[1],()=>next)+source.slice(front.index+front[0].length);}\nfunction editFields(value,fields){inputs=[];by('lib-body').replaceChildren();for(const f of fields){const label=make('label',f.label),area=make('textarea');area.rows=3;area.maxLength=50000;area.value=f.get(value);label.append(area);by('lib-body').append(label);inputs.push({area,set:f.set});}}\nfunction fieldsForDoc(doc){const fields=[];function walk(n,path=[]){if(!n||typeof n!=='object')return;if(n.type==='text'&&typeof n.text==='string'){fields.push({label:'Đoạn chữ '+(fields.length+1),get:()=>n.text,set:(_,v)=>{n.text=v;}});return;}if(Array.isArray(n.content))n.content.forEach((x,i)=>walk(x,[...path,i]));}walk(doc);return fields.slice(0,250);}\nfunction render(){const q=by('lib-query').value.toLocaleLowerCase('vi').trim(),kind=by('lib-kind').value,rows=(snapshot?.rows||[]).filter(r=>(!kind||r.kind===kind)&&(!q||[r.title,r.slug,r.category,r.summary].join(' ').toLocaleLowerCase('vi').includes(q)));by('lib-count').textContent=rows.length+' / '+(snapshot?.rows.length||0)+' bài';const list=by('lib-list');list.replaceChildren();for(const row of rows){const card=make('article');card.className='library-item';card.dataset.kind=row.kind;card.append(make('small',row.kind==='tech'?'Tech Blog':row.category),make('h2',row.title));const link=make('a','Mở bài công khai');link.href=site+row.category+'/'+row.slug+'/';link.target='_blank';link.rel='noopener noreferrer';const edit=make('button','Quản lý bài');edit.type='button';edit.addEventListener('click',()=>open(row));card.append(link,make('br'),edit);list.append(card)}}\nasync function refresh(){if(busy)return;by('lib-refresh').disabled=true;by('lib-status').textContent='Đang tải snapshot phát hành…';try{const r=await fetch('/admin/api/library/',{cache:'no-store',redirect:'error',signal:AbortSignal.timeout(20000)});if(!r.ok)throw Error('upstream');const d=await r.json();if(!validSha(d.sha)||!Array.isArray(d.rows))throw Error('invalid');snapshot=d;by('lib-status').textContent='SHA phát hành: '+d.sha;render()}catch{by('lib-status').textContent='Không tải được thư viện; '+(snapshot?'đang giữ dữ liệu trước.':'thử lại.')}finally{by('lib-refresh').disabled=false}}\nasync function open(row){if(busy)return;const ticket=++selection,sha=snapshot.sha;selected={...row,sha};loaded=null;inputs=[];by('lib-edit').hidden=false;by('lib-edit').scrollIntoView({block:'start'});by('lib-route').textContent=site+row.category+'/'+row.slug+'/';by('lib-version').textContent='Snapshot: '+sha;by('lib-result').textContent='Đang tải bài…';by('lib-body').replaceChildren();by('lib-title').value='';by('lib-summary').value='';by('lib-mode').textContent='';by('lib-confirm').checked=false;by('lib-delete-slug').value='';by('lib-token').value='';by('lib-save').disabled=true;by('lib-delete').disabled=true;\n try{const text=await source(sha,row.path);if(ticket!==selection)return;let state={text};\n if(row.kind==='tech'){const posts=parse(text),post=posts.find(p=>p.slug===row.slug);if(!post)throw Error('Không tìm thấy bài');state={text,posts,post};by('lib-title').value=post.title;by('lib-summary').value=post.summary||'';const fields=post.studioBody?fieldsForDoc(post.studioBody):(post.sections||[]).flatMap((sec,i)=>(sec.paragraphs||[]).map((v,j)=>({label:'Mục '+(i+1)+' · Đoạn '+(j+1),get:()=>sec.paragraphs[j],set:(_,x)=>{sec.paragraphs[j]=x}})));editFields(post,fields.slice(0,250));by('lib-mode').textContent='Chỉnh nội dung chữ hiện có; bố cục, minh họa, slug và metadata khác giữ nguyên.'}\n else{by('lib-title').value=titleField(text,'title');by('lib-summary').value=titleField(text,'description');const indexPath='src/content/docs/'+row.category+'/index.md';const index=await source(sha,indexPath);if(ticket!==selection)return;state.index=index;state.indexPath=indexPath;const id=row.category+'--'+row.slug;const studioPattern=new RegExp('<KnowledgeStudioDocument\\\\s+id=[\"\\']'+id+'[\"\\']\\\\s*/>');if(studioPattern.test(text)){const [docs,meta]=await Promise.all([source(sha,'src/data/studio-documents.json'),source(sha,'src/data/studio-metadata.json')]);if(ticket!==selection)return;state.documents=parse(docs);state.metadata=parse(meta);state.id=id;if(!Object.hasOwn(state.documents,id))throw Error('Thiếu nội dung Studio');editFields(state.documents[id],fieldsForDoc(state.documents[id]));by('lib-mode').textContent='Chỉnh các đoạn chữ trong tài liệu Studio, giữ nguyên định dạng và visual blocks.'}else by('lib-mode').textContent='Bài Markdown/MDX cũ: chỉnh tiêu đề và mô tả. Nội dung, biểu đồ và cấu trúc gốc được giữ nguyên; chưa hỗ trợ sửa thân bài dạng này.';}\n loaded=state;by('lib-result').textContent='Đã tải bài; chưa có thay đổi công khai.';by('lib-save').disabled=false;by('lib-delete').disabled=false;\n }catch(e){if(ticket===selection)by('lib-result').textContent=e.message}}\nfunction plan(row,state,remove){const title=by('lib-title').value.trim(),summary=by('lib-summary').value.trim();if(!remove&&(!title||title.length>180||summary.length>500||/[\\u0000-\\u001f\\u007f]/.test(title+summary)))throw Error('Kiểm tra tiêu đề và mô tả.');if(!remove){for(const {area,set} of inputs){if(!area.value.trim())throw Error('Không để trống đoạn chữ đã xuất bản.');set(state,area.value);}}\n const files=[];const write=(path,content)=>files.push({path,mode:'100644',type:'blob',content});const del=path=>files.push({path,mode:'100644',type:'blob',sha:null});\n if(row.kind==='tech'){const posts=remove?state.posts.filter(p=>p.slug!==row.slug):state.posts;if(!remove){state.post.title=title;state.post.summary=summary;if(state.post.studioBody){const texts=[];const walk=n=>{if(n.type==='text')texts.push(n.text);else(n.content||[]).forEach(walk)};walk(state.post.studioBody);state.post.sections=[{heading:'Nội dung',paragraphs:[texts.join(' ')]}];}}write(row.path,format(posts));}\n else{const route='/khoahoctienghan/'+row.category+'/'+row.slug+'/';const lines=state.index.split('\\n');let matches=0;const next=lines.flatMap(line=>{if(!line.endsWith(']('+route+')')&&!line.endsWith(']('+route+')\\r'))return [line];if(!/^\\s*-\\s+\\[/.test(line))throw Error('Liên kết chuyên mục không hỗ trợ');matches++;return remove?[]:['- ['+title.replace(/[\\\\[\\]<>*_{}&]/g,c=>'&#'+c.charCodeAt(0)+';')+']('+route+')'];});if(matches!==1)throw Error('Cần đúng một liên kết chuyên mục; không tự sửa mơ hồ.');\n write(state.indexPath,next.join('\\n'));if(remove){del(row.path);if(state.id){delete state.documents[state.id];delete state.metadata[state.id];write('src/data/studio-documents.json',format(state.documents));write('src/data/studio-metadata.json',format(state.metadata));}}else{write(row.path,replaceField(replaceField(state.text,'title',title),'description',summary));if(state.id)write('src/data/studio-documents.json',format(state.documents));}}\n return files;}\nasync function submit(remove){if(busy||!loaded||!selected)return;const active=document.activeElement;if(active instanceof HTMLElement&&active.matches('input, textarea, select'))active.blur();const result=by('lib-result');if(!by('lib-confirm').checked){result.textContent='Cần xác nhận gửi lên GitHub.';return}if(remove&&by('lib-delete-slug').value!==selected.slug){result.textContent='Nhập đúng slug để xác nhận đề nghị xóa.';return}const token=by('lib-token').value.trim();by('lib-token').value='';if(!token.startsWith('github'+'_pat_')){result.textContent='Cần fine-grained PAT hợp lệ.';return}const row=selected;busy=true;by('lib-save').disabled=true;by('lib-delete').disabled=true;result.textContent='Đang kiểm tra phiên bản trước khi tạo PR nháp…';try{\n const request=async(path,method='GET',body)=>{const res=await fetch('https://api.github.com'+path,{method,redirect:'error',cache:'no-store',credentials:'omit',headers:{Accept:'application/vnd.github+json',Authorization:'Bearer '+token,'Content-Type':'application/json'},...(body?{body:JSON.stringify(body)}:{})});if(!res.ok)throw Error('GitHub HTTP '+res.status);return res.json();};\n const user=await request('/user'),repository=await request(repo);if(user.login!=='duykhang68'||repository.full_name!=='duykhang68/khoahoctienghan'||repository.permissions?.push!==true)throw Error('Chỉ chủ repo có quyền gửi PR.');\n const main=(await request(repo+'/git/ref/heads/main')).object.sha;if(main!==row.sha)throw Error('Phiên bản main đã đổi hoặc chưa phát hành. Cập nhật thư viện, không ghi đè.');\n const files=plan(row,loaded,remove);const base=await request(repo+'/git/commits/'+main);if((await request(repo+'/git/ref/heads/main')).object.sha!==main)throw Error('Main vừa đổi. Vui lòng tải lại.');\n const tree=await request(repo+'/git/trees','POST',{base_tree:base.tree.sha,tree:files});const action=remove?'delete':'edit';const commit=await request(repo+'/git/commits','POST',{message:'content(library): '+action+' '+row.category+'/'+row.slug,tree:tree.sha,parents:[main]});if((await request(repo+'/git/ref/heads/main')).object.sha!==main)throw Error('Main vừa đổi. Không tạo nhánh.');\n const branch='review/library-'+action+'-'+row.slug.slice(0,60)+'-'+crypto.randomUUID().slice(0,12);await request(repo+'/git/refs','POST',{ref:'refs/heads/'+branch,sha:commit.sha});const pr=await request(repo+'/pulls','POST',{title:'content(library): '+action+' '+row.slug,head:branch,base:'main',draft:true,body:'Đề nghị từ Private Content Library. Không tự merge. Snapshot: '+main+'\\\\nURL: '+site+row.category+'/'+row.slug+'/\\\\nCần kiểm tra diff, CI và review thủ công trước khi chuyển ready.'});const url=new URL(pr.html_url);if(url.origin!=='https://github.com'||!/^\\/duykhang68\\/khoahoctienghan\\/pull\\/\\d+$/.test(url.pathname))throw Error('PR đã gửi nhưng URL không hợp lệ. Kiểm tra GitHub.');const link=make('a','Mở PR nháp #'+pr.number);link.href=url.href;link.target='_blank';link.rel='noopener noreferrer';result.replaceChildren(make('span','Đã tạo PR nháp, chưa merge. '),link);loaded=null;by('lib-confirm').checked=false;\n }catch(e){result.textContent=e.message+' · Kiểm tra PR trên GitHub trước khi thử lại.'}finally{busy=false;by('lib-save').disabled=!loaded;by('lib-delete').disabled=!loaded;}}\nby('lib-query').addEventListener('input',render);by('lib-kind').addEventListener('change',render);by('lib-refresh').addEventListener('click',refresh);by('lib-close').addEventListener('click',()=>{if(busy)return;selection++;selected=null;loaded=null;by('lib-token').value='';by('lib-edit').hidden=true});by('lib-save').addEventListener('click',()=>submit(false));by('lib-delete').addEventListener('click',()=>submit(true));void refresh();\n";
